#!/usr/bin/env python3
"""Déplacer uniquement les commentaires techniques, sans toucher les jetons exécutés.

Les commentaires originaux sont conservés dans docs/COMMENTAIRES-APP-20261019.md.
Chaque ancrage est unique ; les sauts de ligne sont préservés pour les règles ASI.
"""
import os
from pathlib import Path

COMMENTAIRES = ["/* Organigramme à mémoire permanente : un poste de travail en quatre vues (Calendrier, Vitrine, Calculs, Exigences), identité dorée de l'Examen fédéral · Version SSP. */", '/* Fond pâle par défaut */', '/* ---------- ATLAS : sauvegarde (export, import, erreurs de stockage) ---------- */', '/* Format v1 : {format:"organigramme-examen-federal",version:1,exporte:ISO,cles:{"orga-…":"<valeur brute>"}} ; orga-bak (date du dernier export) n’est pas exporté. */', '/* v1 : format initial ; une version future convertira ici les anciennes clés. */', '/* ---------- HERMÈS : sauvegarde automatique fiable (miroir IndexedDB, versions, persistance, fichier) ---------- */', '/* Chaque écriture réussie (lsSet) programme svFlush : copie « cur » dans IndexedDB avec somme FNV-1a, version horaire au plus, 30 versions gardées. */', '/* ---------- MNÉMOSYNE : persistance (base partagée, repli local) ---------- */', '/* ---------- Nomenclature et recherche ---------- */', "/* ---------- CHRONOS : grille au quart d'heure ---------- */", '/* ---------- HERMÈS : calendrier interactif (clic, plage, recherche floue, déplacement, durée, toucher, clavier) ---------- */', '/* Fenêtre de création rapide */', '/* Clic, plage, déplacement et durée */', '/* Clavier : flèches = déplacer de 15 min ou d’un jour ; Maj + flèches = durée ; Entrée = détails */', '/* ---------- ATLAS : agrégats ---------- */', '/* ---------- LOGOS : calculs ---------- */', '/* ---------- Exigences ---------- */', '/* ---------- Onglets et rendu ---------- */', '/* ---------- Affichage : intensité dorée, taille du texte ---------- */', '/* ---------- Mnémosyne : méthodes fondées sur les preuves (assets/memo/mem.js, chargé à la demande) ---------- */', '/* ---------- MNÉMÉ : mémorisation espacée ---------- */', '/* ---------- CS : plan en 6 phases ---------- */', '/* ---------- SCÈNE : générateur de scénarios IA ---------- */', '/* ---------- Journal des simulations CS ---------- */', '/* ---------- ATTENDUS : ce qui est noté, prérequis par épreuve ---------- */', '/* ---------- Notions CK : maîtrise notion par notion, objectif > 95 % ---------- */', '/* ---------- Chiron : stations CS (assets/st/, chargées à la demande) ---------- */', '/* ---------- Gestes d’examen physique ---------- */', '/* ---------- Import du résultat produit par l’IA ---------- */', '/* ---------- Infobulles : l’essentiel pour 100 % des points ---------- */', "/* Contrôles qui gardent leur propre action : un clic dessus n'épingle pas la fenêtre (le petit i et le mot souligné, eux, l'épinglent toujours). */", '/* ---------- HERMÈS · NC-0 : glossaire imbriqué (gloLink), pile de fenêtres, types CK (glo, syn, hyp, nc, loc), couches, vues et états des schémas ---------- */', '/* Données (Atlas, assets/ck/*.js, chargées par ckLoad et ckGlo du patch 0011) : CK_GLO_INDEX.e = [[id, type, libellé, formes, tranche], …] ;\n   définitions par tranche (CK_GLO_A…) ; CK_SYN, CK_HYP, CK_NC, CK_LOC, CK_SRC, CK_DOSES_CH (objet par identifiant ou tableau).\n   Schémas : CK_SVG[chemin du SVG] = texte SVG (assets/nc/ncXX.js, tools/nc_svg_js.py), états dans data-etats (Dédale). Aucune donnée ici. */', '/* Phrase : échappée, avec un point final seulement s’il manque (aucun « .. »). */', '/* Index du glossaire : formes pliées (sans accents ni casse) et sigles exacts (AVC) ; la plus longue forme l’emporte. */', '/* Chargement à la demande : la fenêtre s’affiche (« Chargement… »), puis se redessine sur place quand les fichiers sont là. */', '/* gloLink(racine, exclus, dansFenetre) : pose une clé de glossaire (type glo) sur la première occurrence de chaque terme par bloc ; ignore titres, liens, code,\n   commandes, éléments déjà reliés et identifiants exclus (terme courant et ancêtres de la pile). Ne modifie aucune donnée (TIP, NOT, GES). */', '/* Pages : liaison à l’inactivité, par petits lots, sur les nœuds ajoutés au rendu ; jamais dans la fenêtre (liée à son ouverture). */', '/* Rendus des types CK. ckL : lien explicite vers une autre fenêtre (retiré s’il est déjà dans la pile ou au niveau 5). */', '/* Schémas : SVG en ligne depuis CK_SVG (assets/nc/ncXX.js), nettoyé ; états (data-etats) et couches réglables ; sinon image simple. */', '/* État X : [data-etat] visibles seulement pour X ; couches cochées d’après data-etats[X] (l’utilisateur peut ensuite les régler). */', '/* Couche c : tous ses groupes (#c ou [data-couche=c]) ; un groupe propre à un état (data-etat) ne s’affiche que dans cet état. */', '/* le SVG de Dédale porte déjà son crédit visible */', '/* Repères numérotés (Dédale : g.nc-num, data-num, data-nom, data-glo) : bulle « n · nom » après clic, toucher ou activation clavier ;\n   clic, toucher ou Entrée ouvrent la fiche du glossaire au niveau suivant (même pile), sauf au niveau 5 ou si elle est déjà ouverte. */', '/* Pile de fenêtres : un terme ouvert depuis la fenêtre l’empile (5 niveaux au plus) ; « ← Retour » et le fil d’Ariane y reviennent. */']


def appliquer(source):
    for ancrage in COMMENTAIRES:
        assert source.count(ancrage) == 1, 'Ancrage de commentaire absent ou répété'
        source = source.replace(ancrage, '\n' * ancrage.count('\n') + ' ', 1)
    return source


if __name__ == '__main__':
    path = Path(os.environ.get('APP_FILE', 'app_v2.html'))
    source = path.read_text()
    result = appliquer(source)
    path.write_text(result)
    print(str(len(source.encode()) - len(result.encode())) + ' octets de commentaires déplacés ; jetons et sauts de ligne conservés.')
